 const workload=d.workload.map(w=>`<tr><td><div class="person-cell"><span>${w.initials}</span><div><strong>${w.name}</strong><small>${w.team}</small></div></div></td><td>${w.application}</td><td>${w.open}</td><td>${w.remaining}</td><td>${w.blocked}</td><td>${badge(w.availability)}</td><td>${w.note}</td></tr>`);
